/* Presentation only: all financial values arrive pre-calculated from the API. */
const pages=[['overview','⌂','总览','一眼看清今天该做什么'],['today','⌁','今日操作','按月检查，不需要每天交易'],['assets','▣','持仓与资产','你的钱目前在哪里'],['cashflows','⇄','资金流水','每一笔资金都有记录'],['history','◷','历史记录','回看月度检查与策略历史'],['strategy','ⓘ','策略说明','用简单语言理解策略'],['settings','⚙','设置','执行基金和账户偏好']];
let current='overview', cache={}, sessionState=null, activeAccountId=sessionStorage.getItem('s2-owner-account-id')||'';
const $=s=>document.querySelector(s); const fmt=v=>'¥ '+Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}); const pct=v=>(Number(v||0)*100).toFixed(1)+'%'; const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function eventId(prefix){return `${prefix}-${crypto.randomUUID().replaceAll('-','').slice(0,12)}`}
function accountHeaders(headers=new Headers()){if(activeAccountId)headers.set('X-S2-Account-ID',activeAccountId);return headers}
async function ensureSession(force=false){if(sessionState&&!force)return sessionState;const r=await fetch('/api/session',{headers:accountHeaders(),cache:'no-store'});if(!r.ok)throw new Error('当前账户身份不可用。');const next=await r.json();if(sessionState?.user?.id&&sessionState.user.id!==next.user.id){cache={};$('#content').replaceChildren()}if(next.user.role==='OWNER'&&next.account?.account_id&&!activeAccountId){activeAccountId=next.account.account_id;sessionStorage.setItem('s2-owner-account-id',activeAccountId)}sessionState=next;return next}
async function api(url,opt={}){let r;try{const method=String(opt.method||'GET').toUpperCase(),headers=accountHeaders(new Headers(opt.headers||{}));if(!['GET','HEAD','OPTIONS'].includes(method)){const s=await ensureSession();headers.set('X-CSRF-Token',s.csrf_token)}r=await fetch(url,{...opt,headers,cache:'no-store'})}catch{throw new Error('无法连接后台服务，请稍后重试。')}const ct=r.headers.get('content-type')||'';let x=null;if(ct.includes('application/json')){try{x=await r.json()}catch{throw new Error('后台返回了无法读取的数据，请稍后重试。')}}else if(!r.ok){throw new Error(`操作失败，后台返回${r.status}错误，请稍后重试。`)}if(!r.ok){if([401,403].includes(r.status)){cache={};sessionState=null}throw new Error(x?.detail||`操作失败，后台返回${r.status}错误，请稍后重试。`)}if(x===null)throw new Error('后台未返回有效结果，请稍后重试。');return x}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toast-region').appendChild(el);setTimeout(()=>el.remove(),3600)}
async function downloadPrivate(url,filename){const s=await ensureSession(),headers=accountHeaders(new Headers());const r=await fetch(url,{headers,cache:'no-store'});if(!r.ok)throw new Error('导出失败，请稍后重试。');const objectUrl=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=objectUrl;a.download=filename;a.click();URL.revokeObjectURL(objectUrl)}
function humanError(message){return ({INSUFFICIENT_WITHDRAWABLE_ASSETS:'可提款金额不足，请检查当前可用资产。',AMOUNT_MUST_BE_POSITIVE:'请输入大于 0 的金额。',FUND_SALE_EXCEEDS_FUND:'可赎回基金资产不足。',BUY_CONFIRMATION_DOES_NOT_MATCH_CASH_DEBIT:'确认本金与已记录的平台实际扣款不一致。请先修正订单扣款金额，再录入确认结果。'})[message]||message}
function clearForm(form){form.reset();form.querySelectorAll('.field-error').forEach(x=>x.textContent='');form.querySelectorAll('.input-error').forEach(x=>x.classList.remove('input-error'))}
function closeDialog(id){const d=document.getElementById(id);if(!d)return;if(d.open)d.close();d.removeAttribute('open');d.classList.remove('is-open');document.body.classList.remove('modal-open');if(d.querySelector('form'))clearForm(d.querySelector('form'));if(d._returnFocus?.isConnected)d._returnFocus.focus();d._returnFocus=null}
function closeModal(reason,id='money-dialog'){closeDialog(id)}
function parseAmount(value,{required=true,allowZero=false}={}){const raw=String(value??'').replace(/,/g,'').trim();if(!raw)return required?{error:'请输入金额'}:{value:0};if(/^\s*-/.test(raw))return{error:allowZero?'金额不能为负数':'请输入大于0的金额'};if(!/^\d+(\.\d{1,2})?$/.test(raw))return{error:'请输入有效金额'};const n=Number(raw);if(!Number.isFinite(n)||n<0||(!allowZero&&n<=0))return{error:allowZero?'金额不能为负数':'请输入大于0的金额'};if(n>1e12)return{error:'金额超出允许范围，请检查'};return{value:n}}
function parseConfirmedNav(value){const raw=String(value??'').replace(/,/g,'').trim();if(!raw)return{error:'请输入确认 NAV'};if(/^\s*-/.test(raw)||!/^(?:\d+)(?:\.\d{1,8})?$/.test(raw))return{error:'请输入有效 NAV（最多8位小数）'};const n=Number(raw);if(!Number.isFinite(n)||n<=0)return{error:'请输入大于0的 NAV'};if(n>1e12)return{error:'NAV 超出允许范围，请检查'};return{value:n}}
function fieldError(input,message){const e=document.getElementById(`${input.id}-error`);if(e)e.textContent=message||'';input.classList.toggle('input-error',!!message);return !message}
function shanghaiNow(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).reduce((a,x)=>(a[x.type]=x.value,a),{});return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`}
function contractNow(reference=''){const current=shanghaiNow(),ref=String(reference||'').slice(0,16);return ref&&ref>current?ref:current}
function datetimeIso(value){return value?`${value}:00+08:00`:null}
function confirmDialog(message,action){$('#confirm-message').textContent=message;$('#confirm-dialog').showModal();$('#confirm-form')._action=action}
function renderNav(){ $('#nav').innerHTML=pages.map(([id,icon,name])=>`<button class="nav-item ${id===current?'active':''}" onclick="go('${id}')"><span class="nav-icon">${icon}</span><span class="nav-label">${name}</span></button>`).join('') }
async function renderAccountSwitcher(){const host=$('#account-switcher'),s=sessionState;if(!host||s?.user?.role!=='OWNER'){if(host)host.replaceChildren();return}const x=await api('/api/accounts'),accounts=x.accounts||[],active=accounts.find(a=>a.account_id===activeAccountId)||accounts.find(a=>a.is_default)||accounts[0];if(!active){host.innerHTML=`<section class="account-toolbar account-toolbar-empty" aria-label="账户工具条"><span class="account-toolbar-label">当前账户</span><div class="account-toolbar-controls"><span class="account-empty-state">暂无账户</span><button class="secondary account-create-button" type="button" onclick="createOwnerAccount()">+ 新建账户</button></div></section>`;return}if(active.account_id!==activeAccountId){activeAccountId=active.account_id;sessionStorage.setItem('s2-owner-account-id',activeAccountId)}host.innerHTML=`<section class="account-toolbar" aria-label="账户工具条"><span class="account-toolbar-label">当前账户</span><div class="account-toolbar-controls"><select class="account-select" aria-label="当前投资账户" onchange="selectOwnerAccount(this.value,this.options[this.selectedIndex]?.text)">${accounts.map(a=>`<option value="${esc(a.account_id)}" ${a.account_id===activeAccountId?'selected':''}>${esc(a.display_name)}</option>`).join('')}</select>${active.is_default?'<span class="account-default-badge">默认账户</span>':''}<button class="secondary account-create-button" type="button" onclick="createOwnerAccount()">+ 新建账户</button></div></section>`}
async function selectOwnerAccount(accountId,accountName=''){if(accountId===activeAccountId)return;const previousAccountId=activeAccountId;activeAccountId=accountId;sessionStorage.setItem('s2-owner-account-id',accountId);cache={};sessionState=null;try{await refreshAll();toast(`已切换到：${accountName||'所选账户'}`)}catch(err){activeAccountId=previousAccountId;if(previousAccountId)sessionStorage.setItem('s2-owner-account-id',previousAccountId);else sessionStorage.removeItem('s2-owner-account-id');cache={};sessionState=null;toast(humanError(err.message),'error')}}
function createOwnerAccount(){const d=$('#account-create-dialog');d._returnFocus=document.activeElement;clearForm($('#account-create-form'));d.showModal();d.classList.add('is-open');document.body.classList.add('modal-open');$('#account-create-name').focus()}
$('#account-create-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,display_name=$('#account-create-name').value.trim(),account_type=$('#account-create-type').value;if(!display_name){toast('请输入账户名称。','error');return}try{const r=await api('/api/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name,account_type})});closeDialog('account-create-dialog');await selectOwnerAccount(r.account.account_id);toast('已建立独立空白账户。','success')}catch(err){toast(humanError(err.message),'error')}});
async function refreshAll(){await ensureSession();cache.dashboard=await api('/api/dashboard');const d=cache.dashboard.data_status;$('#data-date').textContent=d.latest_date||'—';$('#data-status').textContent=d.status;$('#data-dot').style.background=d.status==='正常'?'var(--green)':'var(--amber)';await renderAccountSwitcher();render()}
function go(id){current=id;renderNav();render()}
function startCard(){return `<div class="card start-card"><h2>开始使用</h2><p class="neutral">尚未建立策略账户。</p><button class="primary" onclick="openInitialize()">初始化账户</button></div>`}
function metric(k,v){const title=String(k).includes('XIRR')?' title="XIRR：考虑实际加钱和取钱后的个人年化收益率。"':'';return `<div class="metric-row"${title}><span>${k}</span><span>${v}</span></div>`}
function signalLabelText(v){const n=Number(v||0);return n>=.9?'极度便宜':n>=.8?'明显便宜':n>=.6?'偏便宜':n>=.4?'中性':n>=.2?'偏贵':n>=.1?'明显偏贵':'极度偏贵'}
function v5Chart(points){const rows=(points||[]).filter((_,i)=>i%Math.max(1,Math.floor((points||[]).length/180))===0);if(!rows.length)return '<div class="empty">暂无历史数据</div>';const x=i=>i/(rows.length-1||1)*1000,y=v=>220-(Math.max(0,Math.min(1,Number(v)||0))*190);let p='',e='';rows.forEach((r,i)=>{p+=(i?' L':'M')+`${x(i)},${y(r.percentile)}`;const prev=i?Number(rows[i-1].target_exposure)||0:Number(r.target_exposure)||0,cur=Number(r.target_exposure)||0;e+=i?` L${x(i)},${y(prev)} L${x(i)},${y(cur)}`:`M${x(i)},${y(cur)}`});const years=rows.filter((r,i)=>i===0||i===rows.length-1||String(r.date).endsWith('-01-01'));return `<div class="v5-chart"><svg viewBox="0 0 1000 230" preserveAspectRatio="none"><path class="percentile" d="${p}"/><path class="exposure" d="${e}"/>${rows.filter((_,i)=>i%Math.max(1,Math.floor(rows.length/12))===0).map((r,i)=>`<circle cx="${x(rows.indexOf(r))}" cy="${y(r.percentile)}" r="3"><title>${r.date} · Spread ${Number(r.spread).toFixed(2)}% · 分位 ${pct(r.percentile)} · 目标 ${pct(r.target_exposure)}</title></circle>`).join('')}</svg></div><div class="chart-axis"><span>0%</span><span>20%</span><span>40%</span><span>60%</span><span>80%</span><span>100%</span></div><div class="chart-axis">${years.map(r=>`<span>${String(r.date).slice(0,4)}</span>`).join('')}</div><div class="chart-legend"><span><i class="g"></i>S2历史分位</span><span><i class="b"></i>正式目标仓位（阶梯线）</span></div>`}
function openMoney(kind){const d=$('#money-dialog'),withdraw=kind==='withdrawal';d._returnFocus=document.activeElement;clearForm($('#money-form'));$('#form-title').textContent=withdraw?'我要取钱':'新增资金';$('#cleared-wrap').style.display=withdraw?'none':'grid';$('#form-cleared').value=shanghaiNow();$('#form-hint').textContent=withdraw?'默认优先使用备用现金、已清算待配置资金、策略现金，最后才卖出基金；不会触发完整调仓。':'资金先进入待配置资金，只有在月度批次截止前已到账才参与本月调仓。';$('#money-form').dataset.kind=kind;d.showModal();d.classList.add('is-open');document.body.classList.add('modal-open')}
$('#money-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.submitting==='true')return;const kind=form.dataset.kind,amount=parseAmount($('#form-amount').value);if(!fieldError($('#form-amount'),amount.error))return;if(kind==='contribution'&&!$('#form-cleared').value){fieldError($('#form-cleared'),'请选择到账日期与时间');return}form.dataset.submitting='true';$('#form-submit').disabled=true;$('#form-submit').textContent='正在保存…';let body={event_id:eventId(kind==='contribution'?'CONTRIB':'WITHDRAW'),amount:amount.value,note:$('#form-note').value};if(kind==='contribution')body.cleared_at=datetimeIso($('#form-cleared').value);try{let r=await api('/api/'+kind,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.result.status==='REJECTED')throw new Error(r.result.reason||'操作未能完成，请检查输入。');closeDialog('money-dialog');await refreshAll();toast(kind==='contribution'?'新增资金成功，已进入待配置资金。':'提款记录成功。')}catch(err){toast(humanError(err.message),'error')}finally{form.dataset.submitting='false';$('#form-submit').disabled=false;$('#form-submit').textContent='确认记录'}});
function openInitialize(importMode=false){const d=$('#initialize-dialog');d._returnFocus=document.activeElement;clearForm($('#initialize-form'));$('#initialize-form').dataset.importMode=String(importMode);$('#initialize-title').textContent=importMode?'导入已有基金账户':'建立账户';$('#init-import-fields').hidden=!importMode;$('#init-strategy-wrap').hidden=importMode;$('#initialize-submit').textContent=importMode?'导入账户':'建立账户';d.showModal();d.classList.add('is-open');document.body.classList.add('modal-open')}
$('#initialize-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,importing=form.dataset.importMode==='true';let url='/api/initialize',body={event_id:eventId(importing?'IMPORT':'INIT'),note:$('#init-note').value};if(importing){url='/api/import-existing-account';body={...body,fund_code:$('#init-fund-code').value,fund_value:$('#init-fund-value').value||0,fund_shares:$('#init-shares').value||null,strategy_cash:$('#init-cash').value||0,pending_cash:$('#init-pending').value||0,reserve_cash:$('#init-reserve-import').value||0}}else{body={...body,strategy_capital:$('#init-strategy').value,reserve_cash:$('#init-reserve').value||0}}try{const r=await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!['APPLIED','ALREADY_PROCESSED'].includes(r.result.status))throw new Error(r.result.reason||'建立账户失败');closeDialog('initialize-dialog');await refreshAll();toast(importing?'已有账户已导入。':'账户已建立。')}catch(err){toast(humanError(err.message),'error')}});
function testerSharedDataMode(){return sessionState?.identity_provider==='QA_SIGNED'&&sessionState?.user?.role==='TESTER'}
async function updateData(){if(testerSharedDataMode()){try{await refreshAll();toast('已刷新最新已发布数据。','success')}catch(e){toast('刷新已发布数据失败，请稍后重试。','error')}return}try{const r=await api('/api/data-update',{method:'POST'});await refreshAll();toast(r.status==='SUCCESS'?'数据已更新。':r.status==='SKIP_NON_TRADING_DAY'?'今天不是A股交易日。':'数据尚未完整更新，系统保留最近有效数据。',r.status==='SUCCESS'?'success':'warning')}catch(e){toast('数据更新失败，请稍后重试。','error')}}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)closeModal(close.dataset.close,close.dataset.close);if(e.target.tagName==='DIALOG'&&e.target===e.target.closest('dialog'))closeModal('overlay',e.target.id)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=document.querySelector('dialog[open]');if(d)closeModal('escape',d.id)}});
document.addEventListener('change',e=>{if(e.target.id==='set-fund'&&e.target.selectedOptions[0]?.textContent.includes('Y'))toast('Y 类基金为个人养老金专属，请勿用于普通基金账户。','warning')});
document.addEventListener('click',e=>{const link=e.target.closest('a[href="/api/export/backup"],a[href="/api/export/cashflows"]');if(!link)return;e.preventDefault();downloadPrivate(link.getAttribute('href'),link.getAttribute('href').endsWith('backup')?'账户备份.sqlite3':'现金流水.csv').catch(err=>toast(err.message,'error'))});
document.addEventListener('click',e=>{const button=e.target.closest('[data-pending-action]');if(button)openPendingAction(button.dataset.lot,button.dataset.amount,button.dataset.pendingAction,button.dataset.created)});
$('#confirm-form').addEventListener('submit',async e=>{e.preventDefault();const action=e.currentTarget._action;closeDialog('confirm-dialog');if(action)await action()});

/* V5 production views: values are presentation-only and come from API payloads. */
function v5ActionLabel(t){return ({WAIT:'等待月末',BUY:'建议买入',SELL:'建议卖出',HOLD:'本月无需操作',DATA_STALE:'数据需要更新',SIGNAL_BLOCKED:'月末数据不完整，暂不操作'})[t]||t}
function projectionLabel(t){return t?.execution_state==='WAITING_FOR_EXECUTION'?'次交易日待执行':t?.execution_state==='EXECUTION_DAY'?'今天是执行日':t?.execution_state==='CONFIRMATION_PENDING'?'等待基金确认':t?.headline||v5ActionLabel(t?.action)}
function applyProjectionLabels(){const t=cache.dashboard?.today;if(!t)return;const label=projectionLabel(t);document.querySelectorAll('.today-card .badge,.today-hero h1').forEach(x=>{if(!cache.dashboard.execution)x.textContent=label});}
let historyRange='all';
async function setHistoryRange(range){historyRange=range;$('#content').innerHTML=await history()}
async function history(){const h=await api('/api/history'),years=historyRange==='all'?0:Number(historyRange),latest=h.points.at(-1)?.date||'9999-12-31',cutoff=years?`${Number(latest.slice(0,4))-years}${latest.slice(4)}`:'0000-01-01',points=h.points.filter(x=>x.date>=cutoff),signals=h.signals.filter(x=>x.signal_date>=cutoff),executions=h.executions||[],buy=executions.filter(x=>x.actual_action==='BUY').length,sell=executions.filter(x=>x.actual_action==='SELL').length,recent=[...executions].sort((a,b)=>String(b.executed_at).localeCompare(String(a.executed_at)))[0];return `<div class="kpi-grid">${v6Kpi('累计检查次数',h.signals.length,'正式月度记录')}${v6Kpi('已执行买入',buy+' 次','执行记录')}${v6Kpi('已执行卖出',sell+' 次','执行记录')}${v6Kpi('最近一次执行',recent?String(recent.executed_at).slice(0,10):'—',recent?recent.fund_code:'暂无执行记录')}</div><div class="card chart-card"><div class="section-head"><h2>股债利差分位与目标仓位历史</h2><div class="button-row">${[['all','全部历史'],['5','近5年'],['3','近3年'],['1','近1年']].map(x=>`<button class="secondary ${historyRange===x[0]?'active':''}" onclick="setHistoryRange('${x[0]}')">${x[1]}</button>`).join('')}</div></div>${v5Chart(points)}<p class="note">绿色线表示股债利差历史分位，蓝色阶梯线表示当月策略目标仓位。分位越高，通常越偏便宜，对应目标仓位越高。</p></div><h2 style="margin:24px 0 12px">历史大跌中的表现</h2><div class="crisis-grid grid">${Object.entries(h.crisis).map(([k,v])=>`<div class="card"><h2>${esc(k)}</h2>${metric('长期持有最大回撤',pct(v.BuyHold))}${metric('S2最大回撤',pct(v.V2))}${metric('减少回撤',((Number(v.V2)-Number(v.BuyHold))*100).toFixed(1)+' 个百分点')}</div>`).join('')}</div><div class="card flow-table" style="margin-top:18px"><h2>每月 S2 检查记录</h2><table><thead><tr><th>日期</th><th>Spread</th><th>历史分位</th><th>估值状态</th><th>目标仓位</th><th>建议操作</th><th>执行状态</th><th>实际金额</th><th>基金</th></tr></thead><tbody>${signals.map(x=>`<tr><td>${x.signal_date}</td><td>${Number(x.spread).toFixed(2)}%</td><td>${pct(x.percentile)}</td><td>${signalLabelText(x.percentile)}</td><td>${pct(x.target_exposure)}</td><td>${x.action==='BUY'?'买入':x.action==='SELL'?'卖出':'无需操作'}</td><td>${esc(x.execution_status)}</td><td>${x.execution?fmt(x.execution.actual_amount):'—'}</td><td>${x.execution?esc(x.execution.fund_code):'—'}</td></tr>`).join('')}</tbody></table></div>`}
async function saveSettings(){const fee=parseAmount($('#set-fee')?.value,{required:false,allowZero:true}),days=Number($('#set-days')?.value);if(fee.error||!Number.isInteger(days)||days<0||days>10){toast('请检查交易费率和到账天数。','error');return}const body={selected_fund:$('#set-fund').value,profit_lock:$('#set-lock').value,dividend_route:$('#set-dividend').value,fee_rate:fee.value/100,settlement_days:days,beginner_mode:$('#set-beginner')?.checked??true};try{await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await refreshAll();toast('设置已保存。')}catch(e){toast(humanError(e.message),'error')}}
function accountTypeLabel(value){return value==='PENSION'?'个人养老金账户':'普通投资账户'}
function requestAccountTypeChange(){
 const select=$('#set-account-type');if(!select)return;
 const current=select.dataset.current,next=select.value,accountId=select.dataset.accountId,accountName=select.dataset.accountName,isPensionFund=select.dataset.pensionFund==='true';
 if(current===next){toast('账户类型没有变化。');return}
 const message=next==='PENSION'
  ?'确认该账户实际对应个人养老金资金账户或具备个人养老金基金购买资格。该设置仅影响产品资格校验，不改变S2策略和目标仓位。'
  :isPensionFund?'当前执行基金为个人养老金专属Y类份额。改为普通账户后，该基金将进入 PRODUCT_RESTRICTION 状态。':'确认将当前账户改为普通投资账户。该设置仅影响产品资格校验，不改变S2策略和目标仓位。';
 confirmDialog(message,async()=>{try{
  await api(`/api/accounts/${encodeURIComponent(accountId)}/type`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({new_type:next,user_confirmed:true,note:`OWNER UI确认修改：${accountName}`})});
  cache={};await refreshAll();toast(`账户类型已改为${accountTypeLabel(next)}。`,'success')
 }catch(err){select.value=current;toast(humanError(err.message),'error')}})
}
function showExecutionOrder(){const t=cache.dashboard.today,actionable=t.action==='BUY'||t.action==='SELL',units=t.action==='SELL'&&t.recommended_redemption_units!=null?` · 估算赎回 ${Number(t.recommended_redemption_units).toFixed(2)} 份（${t.fund_nav_date}净值 ${Number(t.fund_nav).toFixed(4)}）`:'';toast(actionable?`正式信号 ${t.official_signal_date} · Spread ${Number(t.spread).toFixed(2)}% · 历史分位 ${pct(t.spread_percentile)} · 目标仓位 ${pct(t.target_exposure)} · ${t.action==='BUY'?'买入':'卖出'} ${fmt(t.amount)}${units} · 基金 ${cache.dashboard.account.fund.code}`:'当前没有新的月度执行单。',actionable?'info':'warning')}
async function openExecution(){
 const t=cache.dashboard.today,d=cache.dashboard;if(!t||!['BUY','SELL'].includes(t.action)||d.execution)return;
 const settings=await api('/api/settings'),buy=t.action==='BUY';
 $('#execution-form').dataset.side=t.action;
 $('#execution-summary').textContent=`策略建议${buy?'买入':'卖出'} ${fmt(t.amount)}。实际订单可以不同，但方向必须一致。`;
 $('#execution-amount-title').textContent=buy?'平台实际扣款总额':'平台实际提交赎回份额';
 $('#execution-amount-help').textContent=buy?'包含申购本金和已知费用；账户只按这里记录的实际扣款变化。':'V4 以赎回份额为真实订单输入，金额只作为估算。';
 $('#execution-amount').value=buy?Number(t.amount).toFixed(2):(t.recommended_redemption_units==null?'':Number(t.recommended_redemption_units).toFixed(2));
 $('#execution-fee-wrap').hidden=!buy;$('#execution-estimate-wrap').hidden=buy;
 $('#execution-fee').value='';$('#execution-estimate').value=buy?'':Number(t.amount).toFixed(2);
 $('#execution-at').value=contractNow(`${t.official_signal_date}T16:10`);$('#execution-note').value='';
 $('#execution-fund').innerHTML=settings.funds.filter(x=>x.code===settings.selected_fund).map(x=>`<option value="${x.code}" selected>${x.code} ${esc(x.name)}</option>`).join('');
 const dialog=$('#execution-dialog');dialog._returnFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open');
}
$('#execution-form').addEventListener('submit',async e=>{
 e.preventDefault();const side=e.currentTarget.dataset.side,t=cache.dashboard.today,a=parseAmount($('#execution-amount').value);
 if(!fieldError($('#execution-amount'),a.error))return;
 const fee=parseAmount($('#execution-fee').value,{required:false,allowZero:true});
 const estimate=parseAmount($('#execution-estimate').value,{required:side==='SELL',allowZero:false});
 if(side==='BUY'&&!fieldError($('#execution-fee'),fee.error))return;
 if(side==='SELL'&&!fieldError($('#execution-estimate'),estimate.error))return;
 const payload={event_id:eventId('V4-EXEC'),signal_date:t.official_signal_date,actual_action:side,fund_code:$('#execution-fund').value,reported_at:datetimeIso($('#execution-at').value),note:$('#execution-note').value};
 if(side==='BUY'){payload.cash_debited=a.value;if($('#execution-fee').value.trim())payload.reported_fee=fee.value}else{payload.redemption_units=a.value;payload.estimated_redemption_amount=estimate.value}
 $('#execution-submit').disabled=true;
 try{const r=await api('/api/v4/execution/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeDialog('execution-dialog');await refreshAll();toast(r.result.status==='ALREADY_PROCESSED'?'本月正式信号已经存在执行订单。':'实际订单已记录，等待基金公司确认。')}
 catch(err){toast(humanError(err.message),'error')}finally{$('#execution-submit').disabled=false}
});

function openOrderConfirmation(){
 const ex=cache.dashboard.execution;if(!ex||ex.status!=='PENDING_CONFIRMATION')return;const buy=ex.side==='BUY';
 $('#order-confirm-form').dataset.execution=ex.event_id;$('#order-confirm-summary').textContent=`${buy?'申购':'赎回'}订单 ${ex.event_id} · ${ex.fund_code}`;
 const draft=window.lateConfirmationDraft||{};window.lateConfirmationDraft=null;
 $('#confirm-nav').value=draft.nav||'';$('#confirm-units').value=draft.units||(buy?'':ex.redemption_units||'');
 const base=buy?Number(ex.cash_debited||0)-Number(ex.reported_fee||0):Number(ex.estimated_redemption_amount||0);
 $('#confirm-principal').value=draft.principal|| (base?base.toFixed(2):'');$('#confirm-fee').value=ex.reported_fee||'0';$('#confirm-value').value=draft.value|| (base?base.toFixed(2):'');$('#confirm-reference').value=draft.reference||'';
 $('#order-confirm-correct').hidden=!buy;
 $('#order-confirm-correct').onclick=()=>{const principal=parseAmount($('#confirm-principal').value,{allowZero:true}),fee=parseAmount($('#confirm-fee').value,{allowZero:true});if(principal.error||fee.error){toast('请先填写正确的确认本金和费用。','error');return}const draft={nav:$('#confirm-nav').value,units:$('#confirm-units').value,principal:$('#confirm-principal').value,value:$('#confirm-value').value,reference:$('#confirm-reference').value};closeDialog('order-confirm-dialog');openCorrection({eventId:ex.event_id,side:ex.side,amount:principal.value+fee.value,fee:fee.value,confirmationDraft:draft})};
 const d=$('#order-confirm-dialog');d._returnFocus=document.activeElement;d.showModal();document.body.classList.add('modal-open');
}
$('#order-confirm-form').addEventListener('submit',async e=>{
 e.preventDefault();const values=['nav','units','principal','fee','value'].map(k=>k==='nav'?parseConfirmedNav($(`#confirm-${k}`).value):parseAmount($(`#confirm-${k}`).value,{allowZero:k==='fee'}));if(values.some(x=>x.error)){toast('请完整填写基金确认结果。','error');return}
 const [nav,units,principal,fee,value]=values,execution_event_id=e.currentTarget.dataset.execution;
 $('#order-confirm-submit').disabled=true;
 try{await api('/api/v4/execution/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation_event_id:eventId('V4-CONF'),execution_event_id,confirmed_at:datetimeIso(contractNow(cache.dashboard.execution?.reported_at)),confirmed_nav:nav.value,confirmed_units:units.value,confirmed_principal:principal.value,confirmed_fee:fee.value,confirmed_value:value.value,platform_reference:$('#confirm-reference').value})});closeDialog('order-confirm-dialog');await refreshAll();toast('基金订单确认结果已保存。')}
 catch(err){toast(humanError(err.message),'error')}finally{$('#order-confirm-submit').disabled=false}
});
async function settleExecution(){const ex=cache.dashboard.execution;if(!ex||!['CONFIRMED','WAITING_SETTLEMENT'].includes(ex.status))return;try{await api('/api/v4/execution/settle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({settlement_event_id:eventId('V4-SETTLE'),execution_event_id:ex.event_id,settled_at:datetimeIso(contractNow(ex.reported_at)),destination:'STRATEGY_CASH'})});await refreshAll();toast(ex.side==='SELL'?'赎回款已记入策略现金。':'申购订单已完成。')}catch(err){toast(humanError(err.message),'error')}}

function openPendingAction(lotId,remaining,mode,createdAt=''){const external=mode==='cancel',d=$('#pending-action-dialog');$('#pending-action-form').dataset.lot=lotId;$('#pending-action-form').dataset.mode=mode;$('#pending-action-form').dataset.created=createdAt;$('#pending-action-title').textContent=external?'撤销待配置资金':'转入备用现金';$('#pending-action-summary').textContent=`当前可处理 ${fmt(remaining)}。${external?'资金将离开策略账户，并按当前 NAV 注销账户份额。':'这是账户内部转移，不影响总资产、TWR 或 XIRR。'}`;$('#pending-action-amount').value=Number(remaining).toFixed(2);$('#pending-action-reason').value='';d._returnFocus=document.activeElement;d.showModal();document.body.classList.add('modal-open')}
$('#pending-action-form').addEventListener('submit',async e=>{e.preventDefault();const a=parseAmount($('#pending-action-amount').value);if(!fieldError($('#pending-action-amount'),a.error))return;const mode=e.currentTarget.dataset.mode,url=mode==='cancel'?'/api/v4/pending/cancel':'/api/v4/pending/to-reserve',reference=cache.dashboard.execution?.reported_at||e.currentTarget.dataset.created;$('#pending-action-submit').disabled=true;try{await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_id:eventId(mode==='cancel'?'V4-CANCEL':'V4-RESERVE'),lot_id:e.currentTarget.dataset.lot,amount:a.value,effective_at:datetimeIso(contractNow(reference)),reason:$('#pending-action-reason').value})});closeDialog('pending-action-dialog');await refreshAll();toast(mode==='cancel'?'待配置资金已撤销。':'待配置资金已转入备用现金。')}catch(err){toast(humanError(err.message),'error')}finally{$('#pending-action-submit').disabled=false}});

/* V6 presentation layer. Business values remain API-owned. */
function v6Kpi(label,value,sub,cls=''){return `<div class="card kpi-card ${cls}"><span>${label}</span><strong>${value}</strong><small>${sub||''}</small></div>`}
function v6Thermometer(value){const n=Math.max(0,Math.min(1,Number(value)||0));return `<div class="thermo"><span style="left:${n*100}%"></span></div><div class="thermo-axis"><span>0% 极贵</span><span>40% 中性</span><span>80% 偏便宜</span><span>100% 极度便宜</span></div>`}
function v6Overview(){const d=cache.dashboard,{account:a,today:t,performance:p}=d;if(!a.is_initialized)return startCard();const pctv=t.spread_percentile??t.percentile??0;return `<div class="kpi-grid">${v6Kpi('总资产',fmt(a.total_wealth),'账户全部财富')}${v6Kpi('基金市值',fmt(a.fund_value),a.fund?.name||'当前执行基金')}${v6Kpi('策略现金',fmt(a.strategy_cash),'可按规则参与调仓')}${v6Kpi('待配置资金',fmt(a.pending_cash),'等待正式月度信号')}</div><div class="grid three-main"><div class="card"><h2>我的当前持仓状态</h2><div class="holding-flex"><div class="ring" style="--value:${Number(a.actual_exposure||0)*360}deg"><b>${pct(a.actual_exposure)}</b><small>当前仓位</small></div><div class="holding-info"><b>${esc(a.fund?.name||'未设置基金')} (${esc(a.fund?.code||'—')})</b>${metric('基金市值',fmt(a.fund_value))}${metric('持有份额',a.fund?.shares==null?'—':Number(a.fund.shares).toLocaleString('zh-CN'))}${metric('持有成本',fmt(a.fund?.cost_basis))}${metric('持仓收益',fmt(a.fund?.profit))}</div></div><p class="neutral">目标仓位 ${pct(t.target_exposure)} · 最近正式信号 ${t.official_signal_date||'—'}</p></div><div class="card"><h2>当前 S2 信号</h2><div class="eyebrow">最新观察 ${t.latest_observation_date||'—'}</div><div class="signal-number">${pct(pctv)}</div><div class="signal-state">${signalLabelText(pctv)}</div>${v6Thermometer(pctv)}<p>Spread <b>${Number(t.spread||0).toFixed(2)}%</b><br>正式目标仓位 <b>${pct(t.target_exposure)}</b></p></div><div class="card today-card"><h2>今天是否需要操作？</h2><span class="badge ${t.action==='BUY'?'green':t.action==='SELL'?'red':'gray'}">${d.execution?'本月已执行':v5ActionLabel(t.action)}</span><div class="action-amount">${d.execution?fmt(d.execution.actual_amount):t.action==='BUY'||t.action==='SELL'?fmt(t.amount):'¥ 0.00'}</div><p>${esc(t.explanation||'当前无交易指令')}</p><div class="button-row"><button class="primary" onclick="showExecutionOrder()">生成本月执行单</button><button class="secondary" ${d.execution||!['BUY','SELL'].includes(t.action)?'disabled':''} onclick="openExecution()">${d.execution?'本月已执行':'记录已执行'}</button></div></div></div><div class="card chart-card"><h2>股债利差分位与目标仓位历史</h2>${v5Chart(d.history_points||[])}<p class="neutral">绿色线表示 S2 历史分位，蓝色阶梯线表示正式目标仓位。</p></div><div class="grid overview-support-grid"><div class="card rules-card"><h2>分层规则</h2>${[['≥90%','100%'],['80%-90%','80%'],['60%-80%','60%'],['40%-60%','50%'],['20%-40%','40%'],['10%-20%','20%'],['<10%','0%']].map(x=>`<div class="metric-row ${x[1]===pct(t.target_exposure)?'rule-current':''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="card performance-card"><h2>策略历史表现</h2>${metric('策略 CAGR',pct(p.strategy.cagr))}${metric('最大回撤',pct(p.strategy.mdd))}${metric('Sharpe',Number(p.strategy.sharpe).toFixed(2))}<p class="note">主要优势是降低最大回撤，而不是保证收益高于长期持有。</p></div><div class="card health-card"><h2>数据健康</h2><div class="health-row"><span>000922 中证红利</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div><div class="health-row"><span>ChinaBond 10Y</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div><div class="health-row"><span>007801 NAV</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div><p class="neutral update-time">最后更新：${d.data_status?.latest_update||'—'}</p></div></div>`}
function v6Today(){const d=cache.dashboard,t=d.today,a=d.account;if(!a.is_initialized)return startCard();const ex=d.execution,actionable=['BUY','SELL'].includes(t.action),fund=t.selected_fund||a.fund||{};return `<div class="grid today-layout"><div class="card today-hero"><div class="eyebrow">正式信号日期 ${t.official_signal_date||'—'}</div><h1>${ex?'本月已执行':v5ActionLabel(t.action)}</h1><p>${esc(t.explanation||'当前无交易指令')}</p><div class="hero-money">${ex?fmt(ex.actual_amount):actionable?fmt(t.amount):'¥ 0.00'}</div><div class="metric-grid"><div>正式目标仓位<b>${pct(t.target_exposure)}</b></div><div>当前实际仓位<b>${pct(t.actual_exposure)}</b></div><div>可投资资产<b>${fmt(t.investable_assets)}</b></div><div>净交易金额<b>${fmt(t.net_trade)}</b></div></div><div class="button-row"><button class="primary" onclick="showExecutionOrder()">生成本月执行单</button><button class="secondary" ${ex||!actionable?'disabled':''} onclick="openExecution()">${ex?'本月已执行':'记录已执行'}</button></div></div><div class="card signal-side"><h2>当前 S2 信号</h2><div class="signal-number">${pct(t.spread_percentile)}</div><div class="signal-state">${signalLabelText(t.spread_percentile)}</div>${v6Thermometer(t.spread_percentile)}<p>Spread <b>${Number(t.spread||0).toFixed(2)}%</b></p></div></div><div class="grid two-main"><div class="card"><h2>本次建议依据</h2>${metric('执行基金',esc(`${fund.code||'—'} ${fund.name||''}`))}${metric('执行截止',esc(t.execution_deadline||'—'))}${metric('预计纳入待配置资金',fmt(t.projected_eligible_pending))}${metric('Spread',Number(t.spread||0).toFixed(2)+'%')}${metric('历史分位',pct(t.spread_percentile))}${metric('正式目标仓位',pct(t.target_exposure))}${metric('当前实际仓位',pct(t.actual_exposure))}${metric('目标基金金额',fmt(t.target_fund_value))}${metric('当前基金市值',fmt(a.fund_value))}${metric('净交易金额',fmt(t.net_trade))}</div><div class="card"><h2>操作步骤</h2><div class="steps"><div><b>1</b>查看建议金额</div><div><b>2</b>去基金平台申购或赎回</div><div><b>3</b>回来点击“记录已执行”</div></div></div></div><div class="card secondary-actions"><h2>其他资金操作</h2><button class="secondary" onclick="openMoney('contribution')">新增资金</button> <button class="secondary" onclick="openMoney('withdrawal')">我要取钱</button></div>`}
function v6Assets(){const a=cache.dashboard.account,total=Math.max(1,Number(a.total_wealth));const parts=[['基金市值',a.fund_value,'blue'],['策略现金',a.strategy_cash,'green'],['待配置资金',a.pending_cash,'orange'],['备用/锁定现金',a.reserve_cash,'purple']];return `<div class="kpi-grid">${v6Kpi('总资产',fmt(a.total_wealth),'账户全部财富')}${v6Kpi('基金市值',fmt(a.fund_value),'当前持有基金')}${v6Kpi('待配置资金',fmt(a.pending_cash),'等待月度信号')}${v6Kpi('当前仓位 / 目标仓位',pct(a.actual_exposure)+' / '+pct(cache.dashboard.today.target_exposure),'')}</div><div class="grid two-main"><div class="card"><h2>当前持仓状态</h2><div class="asset-stat"><span>当前仓位<b>${pct(a.actual_exposure)}</b></span><span>目标仓位<b>${pct(cache.dashboard.today.target_exposure)}</b></span><span>距离目标<b>${pct(Number(cache.dashboard.today.target_exposure)-Number(a.actual_exposure))}</b></span></div><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(a.actual_exposure)*100))}%"></i></div><p class="neutral">下一次调仓日：${cache.dashboard.today.next_rebalance_date||'—'} · 每月最后一个交易日检查</p></div><div class="card"><h2>资产分布</h2><div class="asset-list">${parts.map(([n,v,c])=>`<div><i class="dot ${c}"></i><span>${n}</span><b>${fmt(v)}</b><small>${(Number(v||0)/total*100).toFixed(1)}%</small></div>`).join('')}</div></div></div><div class="grid two-main"><div class="card"><h2>当前持有基金</h2>${metric('基金名称',esc(a.fund?.name||'—'))}${metric('基金代码',esc(a.fund?.code||'—'))}${metric('当前市值',fmt(a.fund_value))}${metric('持有份额',a.fund?.shares==null?'—':a.fund.shares)}${metric('成本单价',fmt(a.fund?.cost_basis))}${metric('上次买入日期',a.fund?.last_buy_date||'—')}</div><div class="card"><h2>策略表现 <span class="tip" title="TWR：不考虑个人资金进出，只看策略本身表现。">i</span></h2>${metric('策略本身表现（TWR）',pct(a.twr))}${metric('个人年化收益（XIRR）',a.xirr==null?'—':pct(a.xirr))}<div class="mini-metrics"><span>本月新增资金<b>${fmt(a.month_contributions)}</b></span><span>本月取出资金<b>${fmt(a.month_withdrawals)}</b></span></div></div></div><div class="card"><h2>这里理解更简单</h2><div class="explain-grid"><span><b>基金市值</b>已经买入基金的当前价值</span><span><b>策略现金</b>策略账户中暂未买入的现金</span><span><b>待配置资金</b>等待正式调仓的资金</span><span><b>备用/锁定现金</b>暂不参与策略的资金</span></div></div>`}
function render(){const meta=pages.find(x=>x[0]===current);$('#page-title').textContent=meta[2];$('#page-subtitle').textContent=meta[3];const fn={overview:v6Overview,today:v6Today,assets:v6Assets,cashflows,history,strategy,settings:settingsPage}[current]||v6Overview;Promise.resolve(fn()).then(html=>{$('#content').innerHTML=html;applyProjectionLabels();renderNav();if(current==='settings'){api('/api/settings').then(s=>{if($('#set-dividend'))$('#set-dividend').value=s.dividend_route;if($('#set-lock'))$('#set-lock').value=s.profit_lock})}}).catch(e=>{$('#content').innerHTML=`<div class="card empty">${esc(e.message)}</div>`})}
refreshAll().catch(e=>{$('#content').innerHTML=`<div class="card empty">无法连接本地服务：${esc(e.message)}</div>`});
async function cashflows(){const x=await api('/api/cashflows'),statusText=s=>({APPLIED:'已生效',REJECTED:'已拒绝',ALREADY_PROCESSED:'已处理',PENDING:'待确认'}[s]||s);return `<div class="kpi-grid">${v6Kpi('累计投入',fmt(x.summary.cumulative_contributions),'资金进入账户')}${v6Kpi('累计取出',fmt(x.summary.cumulative_withdrawals),'已提交提款')}${v6Kpi('待配置资金',fmt(x.summary.pending_cash),'尚未纳入正式调仓','orange')}${v6Kpi('当前总资产',fmt(x.summary.total_wealth),'账户全部财富')}</div><div class="grid two-main"><div class="card flow-table"><div class="section-head"><h2>资金流水</h2><div class="button-row"><button class="primary" onclick="openMoney('contribution')">新增资金</button><button class="secondary" onclick="openMoney('withdrawal')">我要取钱</button><button class="secondary" onclick="downloadPrivate('/api/export/cashflows','现金流水.csv')">导出 CSV</button></div></div><table><thead><tr><th>日期时间</th><th>类型</th><th>金额</th><th>状态</th><th>备注</th></tr></thead><tbody>${x.rows.length?x.rows.map(r=>`<tr><td>${esc(String(r.timestamp||'').replace('T',' ').slice(0,16))}</td><td>${esc(r.type)}</td><td>${fmt(r.amount)}</td><td><span class="badge ${statusText(r.status)==='已生效'?'green':statusText(r.status)==='待确认'?'orange':'gray'}">${esc(statusText(r.status))}</span></td><td>${esc(r.note||'')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">暂无资金流水</td></tr>'}</tbody></table></div><div><div class="card"><h2>资金构成一览</h2>${metric('基金市值',fmt(x.summary.fund_value))}${metric('策略现金',fmt(x.summary.strategy_cash))}${metric('待配置资金',fmt(x.summary.pending_cash))}${metric('备用/锁定现金',fmt(x.summary.reserve_cash))}</div><div class="card" style="margin-top:16px"><h2>资金规则</h2><p class="neutral">新增资金先进入待配置资金。当前版本尚未提供待配置资金撤销入口；取现按账户规则执行。</p></div></div></div>`}
async function strategy(){const s=await api('/api/strategy'),p=cache.dashboard.performance;return `<div class="kpi-grid">${v6Kpi('当前历史分位',pct(cache.dashboard.today.spread_percentile),'最新观察')}${v6Kpi('当前 Spread',Number(cache.dashboard.today.spread||0).toFixed(2)+'%','股息率减十年国债')}${v6Kpi('正式目标仓位',pct(cache.dashboard.today.target_exposure),'最近月度信号')}${v6Kpi('最近正式信号',cache.dashboard.today.official_signal_date||'—','只在月度检查')}</div><div class="card"><h2>第一步：这策略到底看什么</h2><div class="steps"><div><b>1</b>中证红利股息率</div><div><b>2</b>减去中国 10 年国债收益率，得到 Spread</div><div><b>3</b>看 Spread 在历史中的分位</div></div><p class="note">Spread = 中证红利股息率 − 中国 10 年国债收益率。利差越高，通常代表股票相对更便宜。</p></div><div class="grid two-main"><div class="card"><h2>第二步：怎么决定仓位</h2>${s.rules.map(x=>`<div class="metric-row"><span>${esc(x[0])}</span><b>${esc(x[1])}</b></div>`).join('')}</div><div class="card"><h2>第三步：长期效果怎么样</h2>${metric('方案','方案三·第七版 / V2 Monthly Target')}${metric('策略 CAGR',pct(p.strategy.cagr))}${metric('策略最大回撤',pct(p.strategy.mdd))}${metric('策略 Sharpe',Number(p.strategy.sharpe).toFixed(2))}${metric('年均操作',Number(p.strategy.annual_trades).toFixed(1)+' 次')}${metric('长期持有 CAGR',pct(p.buyhold.cagr))}${metric('长期持有最大回撤',pct(p.buyhold.mdd))}${metric('长期持有 Sharpe',Number(p.buyhold.sharpe).toFixed(2))}<p class="note">该策略的主要历史优势是降低最大回撤，而不是保证长期收益高于长期持有。</p></div></div><div class="card"><h2>第四步：实际怎么使用</h2><div class="steps"><div><b>1</b>每日自动更新市场数据</div><div><b>2</b>系统计算 Spread 与历史分位</div><div><b>3</b>月末生成正式信号</div><div><b>4</b>用户执行后回来记录</div></div><p class="neutral">历史估值：RESSET DYR_TTM　当前估值：CSI 000922 DY2　10Y：ChinaBond　基金净值：正式 NAV 接口</p></div><div class="warning"><b>本系统是仓位参考与记录工具，不是自动交易系统，也不构成投资建议。</b></div><div class="card fund-registry"><h2>可执行场外基金</h2><div class="fund-list">${s.funds.map(x=>`<div class="fund-row"><span><b>${x.code}</b> ${esc(x.name)}</span><small>${x.share_class||''}类${x.personal_pension_only?' · 个人养老金专属':''}</small></div>`).join('')}</div></div>`}
async function settingsPage(){const s=await api('/api/settings'),ds=cache.dashboard.data_status,sharedTester=testerSharedDataMode();return `<div class="setting-grid"><div class="card setting-card"><h2>默认执行基金</h2><label>当前执行基金<select id="set-fund">${s.funds.map(x=>`<option value="${x.code}" ${x.code===s.selected_fund?'selected':''}>${x.code} ${x.name}</option>`).join('')}</select></label><p class="callout">策略信号：000922 中证红利指数<br>收益回测：H00922 中证红利全收益指数</p></div><div class="card setting-card"><h2>分红与盈利规则</h2><label>分红方式<select id="set-dividend"><option value="REINVEST">红利再投资</option><option value="STRATEGY_CASH">现金进入策略现金</option><option value="RESERVE">现金进入备用现金</option></select></label><label>盈利是否转入锁定现金<select id="set-lock"><option value="0">关闭</option><option value="0.25">锁定 25%</option><option value="0.5">锁定 50%</option></select></label><p class="neutral">开启后，部分盈利转入备用/锁定现金，不继续参与下一轮策略。</p></div><div class="card setting-card"><h2>交易费用与到账设置</h2><label>交易费率（当前值）<input id="set-fee" type="text" inputmode="decimal" value="${Number(s.fee_rate)*100}"></label><label>到账天数（T+N）<input id="set-days" type="text" inputmode="numeric" value="${s.settlement_days}"></label><p class="neutral">当前版本统一用于交易状态估算；后续可分别设置申购确认和赎回到账。</p></div></div><div class="grid two-main"><div class="card"><h2>资金规则</h2>${metric('新增资金','先进入待配置资金')}${metric('月度纳入截止',s.cutoff)}${metric('正式调仓','每月最后一个交易日')}</div><div class="card"><h2>账户与新手模式</h2><label><input id="set-beginner" type="checkbox" ${s.beginner_mode==='true'?'checked':''}> 开启新手模式</label><div class="button-row" style="margin-top:16px"><a class="secondary" href="/api/export/backup">导出账户备份</a><button class="primary" onclick="saveSettings()">保存设置</button></div></div></div><div class="card"><h2>数据源与刷新</h2><p class="neutral">历史估值：${esc(s.data_sources?.historical||'—')}<br>当前估值：${esc(s.data_sources?.current||'—')}<br>国债收益率：${esc(s.data_sources?.bond||'—')}<br>基金净值：${esc(s.data_sources?.fund_nav||'—')}</p><p>当前状态：<span class="health">${esc(ds.status)} · ${esc(ds.latest_date||'—')}</span></p><button class="primary" onclick="updateData()">${sharedTester?'刷新最新已发布数据':'立即更新数据'}</button></div><p class="neutral">本页面仅用于学习与研究用途。参数调整会影响提示金额与回测展示，不构成投资建议。</p>`}

const settingsPageBase = settingsPage;
settingsPage = async function settingsPageFrozen(){
 const html = await settingsPageBase();
 const s=await api('/api/settings'),account=s.account||{},type=account.account_type||'NORMAL',fee=s.selected_fund_fee||{},isOwner=sessionState?.user?.role==='OWNER';
 const version = cache.dashboard?.account?.contract_version || 'S2-account-v4.0-frozen';
 const productText=fee.product_status==='PRODUCT_RESTRICTION'?'PRODUCT_RESTRICTION · 账户类型不匹配':fee.fee_status==='FEE_PARTIAL'?'账户类型匹配 · FEE_PARTIAL':'产品资格匹配';
 const typeControl=isOwner?`<label>账户类型<select id="set-account-type" data-current="${esc(type)}" data-account-id="${esc(account.account_id||'')}" data-account-name="${esc(account.display_name||'')}" data-pension-fund="${fee.configured_product_status==='PENSION_ONLY'}"><option value="NORMAL" ${type==='NORMAL'?'selected':''}>普通投资账户</option><option value="PENSION" ${type==='PENSION'?'selected':''}>个人养老金账户</option></select></label><p class="neutral">仅当该账户实际通过个人养老金资金账户/个人养老金基金渠道执行时选择。账户名称包含“养老金”并不自动代表该类型。</p><p class="callout">当前产品资格：<b>${esc(productText)}</b></p><button class="secondary" type="button" onclick="requestAccountTypeChange()">确认修改账户类型</button>`:`${metric('账户类型',accountTypeLabel(type))}`;
 return html.replace('<h2>账户与新手模式</h2>', `<h2>账户与新手模式</h2><p class="callout">Account Contract<br><b>${esc(version.replace('S2-account-','').replace('v4.0-frozen','V4.0 Frozen'))}</b></p>${typeControl}`);
};

function maintenanceDialog(id,title,body,submit){
 let d=document.getElementById(id);if(!d){d=document.createElement('dialog');d.id=id;document.body.appendChild(d)}
 d.innerHTML=`<form id="${id}-form" novalidate><button type="button" class="icon-btn modal-close" data-close="${id}" aria-label="关闭">×</button><h2>${title}</h2>${body}<div class="modal-footer"><button type="button" class="secondary" data-close="${id}">取消</button><button type="submit" class="primary">确认</button></div></form>`;
 d._returnFocus=document.activeElement;d.showModal();d.classList.add('is-open');document.body.classList.add('modal-open');d.querySelector('form').addEventListener('submit',submit,{once:true});
}
function openLateEntry(){
 maintenanceDialog('maintenance-late-dialog','补录遗漏操作',`<p class="modal-subtitle">这笔操作将按“现在补录”处理，不会重算过去的 TWR/XIRR。真实发生日期仅用于审计记录。</p><label>操作类型<select id="mnt-late-kind"><option value="CONTRIBUTION">补录入金</option><option value="WITHDRAWAL">补录取款</option></select></label><label>真实发生日期<input id="mnt-late-occurred" type="datetime-local" value="${shanghaiNow()}"></label><label>金额（元）<input id="mnt-late-amount" inputmode="decimal"></label><label>原因<input id="mnt-late-reason" maxlength="500"></label><label>备注（可选）<textarea id="mnt-late-note" rows="3"></textarea></label>`,async e=>{e.preventDefault();const amount=parseAmount($('#mnt-late-amount').value);if(amount.error){toast(amount.error,'error');return}try{await api('/api/account-maintenance/late-entry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_id:eventId('MNT-LATE'),kind:$('#mnt-late-kind').value,occurred_at:datetimeIso($('#mnt-late-occurred').value),amount:amount.value,reason:$('#mnt-late-reason').value,note:$('#mnt-late-note').value})});closeDialog('maintenance-late-dialog');await refreshAll();toast('补录已按当前时点入账，历史收益率未重算。')}catch(err){toast(err.message,'error')}});
}

async function openLateExecution(){
 let data;
 try{data=await api('/api/account-maintenance/execution-candidates')}catch(err){toast(err.message,'error');return}
 const c=data.candidate;
 if(!c){toast(data.reason==='SIGNAL_ALREADY_EXECUTED'?'该正式信号已有执行记录。':data.reason==='NO_REBALANCE'?'该正式信号没有调仓动作。':'当前没有可补录的正式信号。','warning');return}
 const fund=c.selected_fund||{}, isBuy=c.recommended_action==='BUY';
 maintenanceDialog('maintenance-execution-dialog','补录基金执行订单',`<p class="modal-subtitle">支持错过执行日后的补录。补录按当前时点写入 V4 账本，真实订单日期仅作审计依据，不会直接改写过去收益率。</p><div class="callout">正式信号 ${esc(c.signal_id)} · ${isBuy?'买入':'卖出'} · 执行基金 ${esc(fund.code||'—')} ${esc(fund.name||'')}<br>执行窗口：${esc(c.execution_date||'—')} 15:00 前 · 建议金额 ${fmt(c.recommended_amount)}</div><label>录入方式<select id="mnt-exec-mode"><option value="MANUAL">手工填写</option><option value="OCR">上传订单截图识别</option></select></label><label>实际订单发生日期<input id="mnt-exec-occurred" type="datetime-local" value="${String(c.execution_date||shanghaiNow()).slice(0,10)}T15:00"></label><label>${isBuy?'平台实际扣款总额':'实际赎回份额'}<input id="mnt-exec-amount" inputmode="decimal" placeholder="${isBuy?'例如 6001.44':'例如 45362.60'}"></label><label>实际费用（元，可留空）<input id="mnt-exec-fee" inputmode="decimal" placeholder="如已知申购费/赎回费"></label>${isBuy?'':'<label>确认 NAV（可选）<input id="mnt-exec-nav" inputmode="decimal"></label><label>确认份额（可选）<input id="mnt-exec-units" inputmode="decimal"></label>'}<label>确认后基金市值（可选）<input id="mnt-exec-value" inputmode="decimal"></label><label>平台流水号（可填多个，用分号分隔）<input id="mnt-exec-reference" maxlength="500"></label><label>订单截图（可选）<input id="mnt-exec-image" type="file" accept="image/png,image/jpeg,image/webp"><button type="button" class="secondary" id="mnt-exec-ocr">识别截图</button></label><p id="mnt-exec-ocr-status" class="neutral">截图识别只会填充草稿，提交前请逐项核对。</p><label>补录原因<input id="mnt-exec-reason" maxlength="500" placeholder="例如：错过执行日，按平台订单补录"></label><label>备注（可选）<textarea id="mnt-exec-note" rows="3" placeholder="多笔订单请先合计金额/费用/份额，并在此说明各笔订单。"></textarea></label>`,async e=>{
  e.preventDefault();
  const amount=parseAmount($('#mnt-exec-amount').value); if(amount.error){toast(amount.error,'error');return}
  const feeRaw=$('#mnt-exec-fee').value.trim(), fee=feeRaw?parseAmount(feeRaw,{allowZero:true}):{value:null}; if(fee.error){toast(fee.error,'error');return}
  const occurred=$('#mnt-exec-occurred').value, reason=$('#mnt-exec-reason').value.trim(); if(!occurred||!reason){toast('请填写实际发生时间和补录原因。','error');return}
  const form=e.currentTarget;
  const payload={event_id:eventId('MNT-EXEC-LATE'),kind:'EXECUTION_REPORTED',occurred_at:datetimeIso(occurred),reported_status:'PENDING_CONFIRMATION',signal_id:c.signal_id,recommendation_id:c.recommendation_id,recommended_action:c.recommended_action,recommended_amount:Number(c.recommended_amount),actual_action:c.recommended_action,fund_code:fund.code,reason,note:$('#mnt-exec-note').value,platform_reference:$('#mnt-exec-reference').value.trim(),ocr_image_sha256:form.dataset.ocrSha||null,ocr_filename:form.dataset.ocrFilename||''};
  if(isBuy)payload.cash_debited=amount.value;else payload.redemption_units=amount.value; if(fee.value!=null)payload.reported_fee=fee.value;
  try{await api('/api/account-maintenance/late-entry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const draft={nav:$('#mnt-exec-nav')?.value,units:$('#mnt-exec-units')?.value,value:$('#mnt-exec-value')?.value,reference:$('#mnt-exec-reference').value};closeDialog('maintenance-execution-dialog');await refreshAll();window.lateConfirmationDraft=draft;toast('基金订单已补录，等待基金确认结果。');openOrderConfirmation()}catch(err){toast(err.message,'error')}
 });
 const form=$('#maintenance-execution-dialog-form'), file=$('#mnt-exec-image'), status=$('#mnt-exec-ocr-status');
 $('#mnt-exec-ocr').onclick=async()=>{if(!file.files?.[0]){toast('请先选择订单截图。','warning');return}const f=file.files[0];status.textContent='正在识别截图…';const reader=new FileReader();reader.onload=async()=>{try{const r=await api('/api/account-maintenance/order-ocr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image_data:reader.result,filename:f.name})});const fields=r.fields||{};if(fields.cash_debited&&isBuy)$('#mnt-exec-amount').value=fields.cash_debited;if(fields.confirmed_units&&!isBuy)$('#mnt-exec-amount').value=fields.confirmed_units;if(fields.reported_fee)$('#mnt-exec-fee').value=fields.reported_fee;if(fields.occurred_at)$('#mnt-exec-occurred').value=fields.occurred_at.slice(0,16);if(fields.platform_reference)$('#mnt-exec-reference').value=fields.platform_reference;form.dataset.ocrSha=r.image_sha256||'';form.dataset.ocrFilename=f.name;status.textContent=(r.warnings||[]).join(' ')||'识别完成，请核对所有字段后提交。';}catch(err){status.textContent=err.message;toast(err.message,'error')}};reader.readAsDataURL(f)};
}
function openCorrection(defaults={}){
 maintenanceDialog('maintenance-correction-dialog','修正错误记录',`<p class="modal-subtitle">仅支持尚未确认的订单。原始记录会永久保留，新记录会形成修正链。</p><label>原订单 Event ID<input id="mnt-corr-event" maxlength="100" value="${esc(defaults.eventId||'')}"></label><label>订单方向<select id="mnt-corr-side"><option value="BUY" ${defaults.side==='SELL'?'':'selected'}>买入：实际扣款</option><option value="SELL" ${defaults.side==='SELL'?'selected':''}>卖出：实际赎回份额</option></select></label><label>实际金额 / 份额<input id="mnt-corr-amount" inputmode="decimal" value="${esc(defaults.amount??'')}"></label><label>已知费用（买入，可留空）<input id="mnt-corr-fee" inputmode="decimal" value="${esc(defaults.fee??'')}"></label><label>修正原因<input id="mnt-corr-reason" maxlength="500" value="${defaults.eventId?'平台实际订单金额与原记录不一致':''}"></label><label>备注（可选）<textarea id="mnt-corr-note" rows="3"></textarea></label>`,async e=>{e.preventDefault();const amount=parseAmount($('#mnt-corr-amount').value);if(amount.error){toast(amount.error,'error');return}try{const event=$('#mnt-corr-event').value.trim(),reason=$('#mnt-corr-reason').value.trim();if(!event)throw new Error('请输入原订单 Event ID。');if(!reason)throw new Error('请输入修正原因。');const side=$('#mnt-corr-side').value,feeRaw=$('#mnt-corr-fee').value.trim(),fee=feeRaw?parseAmount(feeRaw,{allowZero:true}):{value:null};if(fee.error)throw new Error(fee.error);const payload={correction_event_id:eventId('MNT-CORR'),references_event_id:event,reason,note:$('#mnt-corr-note').value};payload[side==='BUY'?'cash_debited':'redemption_units']=amount.value;if(side==='BUY'&&fee.value!=null)payload.reported_fee=fee.value;await api('/api/account-maintenance/correction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeDialog('maintenance-correction-dialog');await refreshAll();toast('原订单已保留，新修正订单正在等待确认。');if(defaults.confirmationDraft){window.lateConfirmationDraft=defaults.confirmationDraft;openOrderConfirmation()}}catch(err){toast(humanError(err.message),'error')}});
}
async function openArchives(){
 try{const data=await api('/api/account-maintenance/archives');const rows=data.archives.map(x=>`<tr><td>${esc(x.account_id)}</td><td>${esc(String(x.created_at||'').slice(0,10))}</td><td>${esc(String(x.archived_at||'').replace('T',' ').slice(0,16))}</td><td>${fmt(x.ending_wealth)}</td><td>${esc(x.reason||'—')}</td><td><button class="secondary" data-archive-export="${esc(x.account_id)}">导出</button></td></tr>`).join('');maintenanceDialog('maintenance-archive-dialog','历史账本（只读）',`<p class="modal-subtitle">归档账本只能查看或导出，不能恢复为当前账户。</p><table><thead><tr><th>账本</th><th>开始日期</th><th>归档时间</th><th>结束资产</th><th>原因</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty">暂无归档账本</td></tr>'}</tbody></table>`,async e=>e.preventDefault());document.querySelectorAll('[data-archive-export]').forEach(button=>button.onclick=async()=>{try{const s=await ensureSession(),r=await fetch('/api/account-maintenance/archives/'+encodeURIComponent(button.dataset.archiveExport)+'/export',{method:'POST',headers:{'X-CSRF-Token':s.csrf_token},cache:'no-store'});if(!r.ok)throw new Error('导出失败，请稍后重试。');const u=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=u;a.download='历史账本.sqlite3';a.click();URL.revokeObjectURL(u);toast('归档账本已导出。')}catch(err){toast(err.message,'error')}})}catch(err){toast(err.message,'error')}
}
async function openRestart(){
 let prep;try{prep=await api('/api/account-maintenance/restart/prepare',{method:'POST'})}catch(err){toast(err.message,'error');return}
 maintenanceDialog('maintenance-restart-dialog','归档当前账户并重新开始',`<p class="warning">旧账本会永久只读保存，新账本从新的真实资产基线重新统计。当前账户：${esc(prep.account_id)}</p><label>确认文字<input id="mnt-restart-confirm" placeholder="请输入：重新开始"></label><label>归档原因<input id="mnt-restart-reason" maxlength="500"></label><label>基线日期<input id="mnt-restart-date" type="datetime-local" value="${shanghaiNow()}"></label><label>基金代码（持有基金时必填）<input id="mnt-restart-fund-code" maxlength="6" placeholder="例如 007801"></label><label>基金份额<input id="mnt-restart-units" inputmode="decimal" value="0"></label><label>基金净值<input id="mnt-restart-nav" inputmode="decimal" value="0"></label><label>基金市值<input id="mnt-restart-value" inputmode="decimal" value="0"></label><label>策略现金<input id="mnt-restart-cash" inputmode="decimal" value="0"></label><label>备用现金<input id="mnt-restart-reserve" inputmode="decimal" value="0"></label><label>待配置资金<input id="mnt-restart-pending" inputmode="decimal" value="0"></label><label>申购待确认<input id="mnt-restart-subscription" inputmode="decimal" value="0"></label><label>赎回待到账<input id="mnt-restart-receivable" inputmode="decimal" value="0"></label><label>事实依据说明<input id="mnt-restart-evidence" maxlength="1000" placeholder="例如：基金平台持仓与现金余额已核对"></label>`,async e=>{e.preventDefault();try{const read=id=>parseAmount($(id).value,{allowZero:true}).value;await api('/api/account-maintenance/restart/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation_id:eventId('MNT-RESTART'),confirmation:$('#mnt-restart-confirm').value,reason:$('#mnt-restart-reason').value,baseline_date:datetimeIso($('#mnt-restart-date').value),fund_code:$('#mnt-restart-fund-code').value.trim()||null,fund_units:read('#mnt-restart-units'),fund_nav:read('#mnt-restart-nav'),fund_value:read('#mnt-restart-value'),strategy_cash:read('#mnt-restart-cash'),reserve_cash:read('#mnt-restart-reserve'),pending_cash:read('#mnt-restart-pending'),subscription_pending:read('#mnt-restart-subscription'),redemption_receivable:read('#mnt-restart-receivable'),evidence_note:$('#mnt-restart-evidence').value})});closeDialog('maintenance-restart-dialog');cache={};await refreshAll();toast('旧账本已归档，新账本已建立。')}catch(err){toast(err.message,'error')}});
}
