/* Account Contract V4 views. All calculations and state transitions remain API-owned. */
function executionMeta(ex){
 if(!ex)return {label:'未记录',cls:'gray',amount:null};
 const labels={PENDING_CONFIRMATION:'等待基金确认',CONFIRMED:'订单已确认',WAITING_SETTLEMENT:'等待赎回到账',SETTLED:'本月已完成'};
 return {label:labels[ex.status]||ex.status,cls:ex.status==='SETTLED'?'green':'orange',amount:ex.side==='BUY'?ex.cash_debited:ex.estimated_redemption_amount};
}
function executionButtons(t,ex){if(!ex)return `<button class="secondary" ${!['BUY','SELL'].includes(t.action)?'disabled':''} onclick="openExecution()">记录实际订单</button>`;if(ex.status==='PENDING_CONFIRMATION')return `<button class="primary" onclick="openOrderConfirmation()">录入基金确认结果</button>`;if(['CONFIRMED','WAITING_SETTLEMENT'].includes(ex.status))return `<button class="primary" onclick="settleExecution()">${ex.side==='SELL'?'确认赎回到账':'完成申购记录'}</button>`;return `<button class="secondary" disabled>本月已完成</button>`}
function v6Overview(){
 const d=cache.dashboard,{account:a,today:t,performance:p}=d;if(!a.is_initialized)return startCard();const ex=d.execution,m=executionMeta(ex),pctv=t.spread_percentile??0;
 return `<div class="kpi-grid">${v6Kpi('总资产',fmt(a.total_wealth),'账户全部财富')}${v6Kpi('基金市值',fmt(a.fund_value),a.fund?.name||'当前执行基金')}${v6Kpi('策略现金',fmt(a.strategy_cash),'可按规则参与调仓')}${v6Kpi('待配置资金',fmt(a.pending_cash),'等待正式月度信号')}</div><div class="grid three-main"><div class="card"><h2>我的当前持仓状态</h2><div class="holding-flex"><div class="ring" style="--value:${Number(a.actual_exposure||0)*360}deg"><b>${pct(a.actual_exposure)}</b><small>当前仓位</small></div><div class="holding-info"><b>${esc(a.fund?.name||'未设置基金')} (${esc(a.fund?.code||'—')})</b>${metric('基金市值',fmt(a.fund_value))}${metric('持有份额',a.fund?.shares==null?'—':Number(a.fund.shares).toLocaleString('zh-CN'))}${metric('申购待确认',fmt(a.subscription_pending))}${metric('赎回待到账',fmt(a.redemption_receivable))}</div></div><p class="neutral">目标仓位 ${pct(t.target_exposure)} · 最近正式信号 ${t.official_signal_date||'—'}</p></div><div class="card"><h2>当前 S2 信号</h2><div class="eyebrow">最新观察 ${t.latest_observation_date||'—'}</div><div class="signal-number">${pct(pctv)}</div><div class="signal-state">${signalLabelText(pctv)}</div>${v6Thermometer(pctv)}<p>Spread <b>${Number(t.spread||0).toFixed(2)}%</b><br>正式目标仓位 <b>${pct(t.target_exposure)}</b></p></div><div class="card today-card"><h2>今天是否需要操作？</h2><span class="badge ${ex?m.cls:t.action==='BUY'?'green':t.action==='SELL'?'red':'gray'}">${ex?m.label:v5ActionLabel(t.action)}</span><div class="action-amount">${ex&&m.amount!=null?fmt(m.amount):['BUY','SELL'].includes(t.action)?fmt(t.amount):'¥ 0.00'}</div><p>${esc(t.explanation||'当前无交易指令')}</p><div class="button-row"><button class="primary" onclick="showExecutionOrder()">生成本月执行单</button>${executionButtons(t,ex)}</div></div></div><div class="card chart-card"><h2>股债利差分位与目标仓位历史</h2>${v5Chart(d.history_points||[])}<p class="neutral">绿色线表示 S2 历史分位，蓝色阶梯线表示正式目标仓位。</p></div><div class="grid overview-support-grid"><div class="card rules-card"><h2>分层规则</h2>${[['≥90%','100%'],['80%-90%','80%'],['60%-80%','60%'],['40%-60%','50%'],['20%-40%','40%'],['10%-20%','20%'],['<10%','0%']].map(x=>`<div class="metric-row ${x[1]===pct(t.target_exposure)?'rule-current':''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="card performance-card"><h2>策略历史表现</h2>${metric('策略 CAGR',pct(p.strategy.cagr))}${metric('最大回撤',pct(p.strategy.mdd))}${metric('Sharpe',Number(p.strategy.sharpe).toFixed(2))}<p class="note">主要优势是降低最大回撤，而不是保证收益高于长期持有。</p></div><div class="card health-card"><h2>数据健康</h2><div class="health-row"><span>000922 中证红利</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div><div class="health-row"><span>ChinaBond 10Y</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div><div class="health-row"><span>${esc(a.fund?.code||'007801')} NAV</span><b>正常</b><time>${d.data_status?.latest_date||'—'}</time></div></div></div>`;
}
